```python
import numpy as np
import random

class Model:
    def __init__(self):
        self.weights = None

    def update(self, context, action, reward):
        raise NotImplementedError("This method should be overridden by subclasses")

    def predict(self, context):
        raise NotImplementedError("This method should be overridden by subclasses")

class LinearModel(Model):
    def __init__(self, num_features):
        super().__init__()
        self.num_features = num_features
        self.weights = np.zeros(num_features)

    def update(self, context, action, reward):
        # Update weights based on the observed reward
        gradient = context * (reward - self.predict(context))
        self.weights += 0.1 * gradient

    def predict(self, context):
        return np.dot(context, self.weights)

class RandomModel(Model):
    def __init__(self):
        super().__init__()

    def update(self, context, action, reward):
        pass

    def predict(self, context):
        return random.uniform(0, 1)

class EpsilonGreedyBandit:
    def __init__(self, models, epsilon=0.1):
        self.models = models
        self.epsilon = epsilon
        self.best_model_index = 0

    def select_action(self, context):
        if random.random() < self.epsilon:
            return random.randint(0, len(self.models) - 1)
        else:
            predictions = [model.predict(context) for model in self.models]
            best_prediction = max(predictions)
            best_model_index = predictions.index(best_prediction)
            return best_model_index

    def update(self, context, action, reward):
        self.models[action].update(context, action, reward)
        if self.models[action].predict(context) > self.models[self.best_model_index].predict(context):
            self.best_model_index = action

# Example usage
if __name__ == "__main__":
    num_features = 5
    num_models = 3
    num_contexts = 1000

    # Initialize models
    linear_model = LinearModel(num_features)
    random_model = RandomModel()
    another_linear_model = LinearModel(num_features)

    models = [linear_model, random_model, another_linear_model]

    # Initialize bandit
    bandit = EpsilonGreedyBandit(models, epsilon=0.1)

    # Simulate contexts and rewards
    for t in range(num_contexts):
        context = np.random.rand(num_features)
        action = bandit.select_action(context)
        reward = np.random.normal(loc=models[action].predict(context), scale=0.1)

        # Update the bandit with the new information
        bandit.update(context, action, reward)

    print("Best model index:", bandit.best_model_index)
```

### Explanation:
1. **Model Class**: This is an abstract base class for all models. It defines the interface for updating and predicting.
2. **LinearModel Class**: A concrete implementation of a linear model. It updates its weights based on the observed reward.
3. **RandomModel Class**: A simple model that always predicts a random value between 0 and 1.
4. **EpsilonGreedyBandit Class**: Implements the epsilon-greedy strategy for selecting actions. It maintains a list of models and selects the best one based on their predictions.
5. **Example Usage**: Demonstrates how to use the above classes to simulate a CMAB scenario.

This script provides a basic framework for implementing a CMAB with multiple models. You can extend it further by adding more sophisticated models or strategies.

