        counter = counter + 1;

        ledRed.write(true);
        ThisThread::sleep_for(500ms);
        ledRed.write(false);
        ThisThread::sleep_for(500ms);

        if (counter > 20) {
            stopThread = true;
            thread2.join();
            thread3.join();
            break;
        }
    }
}
```

