public void MergeWordDocuments(string sourceDoc1Path, string sourceDoc2Path, string outputDocPath)
{
    // Open the first document
    using (WordprocessingDocument doc1 = WordprocessingDocument.Open(sourceDoc1Path, false))
    {
        MainDocumentPart mainPart1 = doc1.MainDocumentPart;

        // Get the body of the first document
        Body body1 = mainPart1.Document.Body;

        // Create a new document for the merged content
        using (WordprocessingDocument mergedDoc = WordprocessingDocument.Create(outputDocPath, WordprocessingDocumentType.Document))
        {
            MainDocumentPart mainPartMerged = mergedDoc.AddMainDocumentPart();
            mainPartMerged.Document = new Document(new Body());

            // Copy the header, footer, and style information from the first document
            foreach (var part in mainPart1.HeaderParts)
            {
                mainPartMerged.HeaderParts.Add(part.CloneNode(true));
            }

            foreach (var part in mainPart1.FooterParts)
            {
                mainPartMerged.FooterParts.Add(part.CloneNode(true));
            }

            foreach (var part in mainPart1.StyleDefinitionsPart.Styles)
            {
                mainPartMerged.StyleDefinitionsPart.Styles.Append(part.CloneNode(true));
            }

            // Add the first two pages of the first document
            int pageCount = 0;
            foreach (Paragraph paragraph in body1.Elements<Paragraph>())
            {
                if (pageCount >= 2) break;

                Paragraph p = new Paragraph(paragraph.CloneNode(true));
                mainPartMerged.Document.Body.Append(p);
                pageCount++;
            }
        }
    }

    // Open the second document
    using (WordprocessingDocument doc2 = WordprocessingDocument.Open(sourceDoc2Path, false))
    {
        MainDocumentPart mainPart2 = doc2.MainDocumentPart;

        // Get the body of the second document
        Body body2 = mainPart2.Document.Body;

        // Append the remaining content of the second document
