Here's a complete example of how you might set this up:

```javascript
const { Client, GatewayIntentBits } = require('discord.js');
const { joinVoiceChannel, createAudioPlayer, createAudioResource, AudioPlayerStatus } = require('@discordjs/voice');

// Replace 'YOUR_BOT_TOKEN' with your actual bot token
const client = new Client({ intents: [GatewayIntentBits.Guilds, GatewayIntentBits.GuildVoiceStates] });

client.once('ready', () => {
  console.log(`Logged in as ${client.user.tag}!`);
});

client.on('interactionCreate', async (interaction) => {
  if (!interaction.isCommand()) return;

  const { commandName } = interaction;

  if (commandName === 'play') {
    // Check if the user is in a voice channel
    if (!interaction.member.voice.channel) {
      return interaction.reply({ content: 'You need to be in a voice channel to use this command.', ephemeral: true });
    }

    // Join the user's voice channel
    const connection = joinVoiceChannel({
      channelId: interaction.member.voice.channel.id,
      guildId: interaction.guild.id,
      adapterCreator: interaction.guild.voiceAdapterCreator,
    });

    // Create an audio player
    const player = createAudioPlayer();

    // Connect the player to the connection
    connection.subscribe(player);

    // Play the audio resource
    const resource = createAudioResource('./path/to/your/audiofile.mp3'); // Replace with the path to your audio file
    player.play(resource);

    // Handle when the audio finishes playing
    player.on(AudioPlayerStatus.Idle, () => {
      console.log('Finished playing audio.');
      connection.destroy(); // Disconnect from the voice channel
    });

    await interaction.reply('Playing audio...');
  }
});

client.login('YOUR_BOT_TOKEN');
```

