```typescript
class SimpleRNN {
  private weights: number[][];
  private biases: number[];

  constructor(inputSize: number, hiddenSize: number, outputSize: number) {
    this.weights = [
      // Input to hidden layer weights
      Array.from({ length: inputSize }, () => Array(hiddenSize).fill(0)),
      // Hidden to hidden layer weights
      Array.from({ length: hiddenSize }, () => Array(hiddenSize).fill(0)),
      // Hidden to output layer weights
      Array.from({ length: hiddenSize }, () => Array(outputSize).fill(0))
    ];

    this.biases = [Array(hiddenSize).fill(0), Array(outputSize).fill(0)];
  }

  public forward(input: number[]): number[] {
    const hiddenState = this.activate(this.weights[0].map((row, i) => row.reduce((sum, weight, j) => sum + input[j] * weight, 0)) + this.biases[0]);
    const output = this.activate(this.weights[2].map((row, i) => row.reduce((sum, weight, j) => sum + hiddenState[j] * weight, 0)) + this.biases[1]);

    return output;
  }

  private activate(x: number): number {
    // Sigmoid activation function
    return 1 / (1 + Math.exp(-x));
  }
}

// Example usage:
