use std::fs;
use std::io::{self, BufRead};
use std::process::Command;

fn main() -> io::Result<()> {
    // Read the input file containing URLs
    let url_file = "urls.txt";
    let urls: Vec<String> = fs::read_to_string(url_file)?
        .lines()
        .map(|line| line.to_string())
        .collect();

    // Separate YouTube URLs from other URLs
    let mut youtube_urls = Vec::new();
    for url in &urls {
        if is_youtube_url(url) {
            youtube_urls.push(url.clone());
        }
    }

    // Download the YouTube URLs using yt-dlp
    for url in youtube_urls {
        Command::new("yt-dlp")
            .arg(url)
            .output()?;
    }

    Ok(())
