Now, let's define the `SierpinskiTriangleControl` class in your code-behind file (e.g., `MainWindow.xaml.cs`):

```csharp
using System.Windows;
using System.Windows.Controls;

namespace SierpinskiTriangle
{
    public partial class MainWindow : Window
    {
        public MainWindow()
        {
            InitializeComponent();
            sierpinskiControl.Draw(100, 10, 200, 200, 3); // Start with the top-left corner at (100, 10), bottom-right at (200, 200), and depth level 3.
        }
    }

    public class SierpinskiTriangleControl : Control
    {
        private void Draw(double x1, double y1, double x2, double y2, int depth)
        {
            if (depth == 0) return;

            var canvas = new Canvas();

            // Calculate midpoints for the three sides of the current triangle
            var m1 = new Point((x1 + x2) / 2, (y1 + y2) / 2);
            var m2 = new Point((x1 + (x1 + x2) / 2), (y1 + (y1 + y2) / 2));
            var m3 = new Point(((x1 + x2) / 2) + ((x2 - x1) / 2), (y1 + (y1 + y2) / 2));

            // Draw the three smaller triangles
            Draw(x1, y1, m1.X, m1.Y, depth - 1);
            Draw(m1.X, m1.Y, m2.X, m2.Y, depth - 1);
            Draw(m2.X, m2.Y, x2, y2, depth - 1);

            // Add the current triangle to the canvas
            var polygon = new Polygon { Points = new PointCollection { new Point(x1, y1), new Point(x2, y2), m1 }, Fill = Brushes.LightBlue };
